mapper.select:
SELECT 


    AND waitlist.status = #{status}
    AND slot.schedule_date = #{scheduleDate}
    AND department.id = #{departmentId}
    AND doctor.id = #{doctorId}

        AND (patient.real_name LIKE CONCAT('%', #{patientKeyword}, '%')
             OR account.name LIKE CONCAT('%', #{patientKeyword}, '%')
             OR account.username LIKE CONCAT('%', #{patientKeyword}, '%')
             OR account.phone LIKE CONCAT('%', #{patientKeyword}, '%'))


ORDER BY waitlist.created_at DESC, waitlist.id DESC
